        public IEnumerable<IModContext<IFallout3Mod, IFallout3ModGetter, IMajorRecord, IMajorRecordGetter>> EnumerateMajorRecordContexts(
            IWorldspaceGetter obj,
            ILinkCache linkCache,
            ModKey modKey,
            IModContext? parent,
            Func<IFallout3Mod, IWorldspaceGetter, IWorldspace> getOrAddAsOverride,
            Func<IFallout3Mod, IWorldspaceGetter, string?, FormKey?, IWorldspace> duplicateInto)
        {
            var curContext = new ModContext<IFallout3Mod, IFallout3ModGetter, IWorldspace, IWorldspaceGetter>(
                modKey,
                record: obj,
                getOrAddAsOverride: getOrAddAsOverride,
                duplicateInto: duplicateInto,
                parent: parent);
            {
                if (obj.TopCell is {} WorldspaceTopCellitem)
                {
                    yield return new ModContext<IFallout3Mod, IFallout3ModGetter, ICellInternal, ICellGetter>(
                        modKey: modKey,
                        record: WorldspaceTopCellitem,
                        parent: curContext,
                        getOrAddAsOverride: (m, r) =>
                        {
                            var baseRec = getOrAddAsOverride(m, linkCache.Resolve<IWorldspaceGetter>(obj.FormKey));
                            if (baseRec.TopCell != null) return baseRec.TopCell;
                            var copy = r.DeepCopy(ModContextExt.CellCopyMask);
                            baseRec.TopCell = copy;
                            return copy;
                        },
                        duplicateInto: (m, r, e, f) =>
                        {
                            var baseRec = getOrAddAsOverride(m, linkCache.Resolve<IWorldspaceGetter>(obj.FormKey));
                            var dupRec = r.Duplicate(f ?? m.GetNextFormKey(e), ModContextExt.CellCopyMask);
                            baseRec.TopCell = dupRec;
                            return dupRec;
                        });
                    foreach (var item in ((CellCommon)((ICellGetter)WorldspaceTopCellitem).CommonInstance()!).EnumerateMajorRecordContexts(
                        obj: WorldspaceTopCellitem,
                        linkCache: linkCache,
                        modKey: modKey,
                        parent: curContext,
                        getOrAddAsOverride: (m, r) =>
                        {
                            var baseRec = getOrAddAsOverride(m, linkCache.Resolve<IWorldspaceGetter>(obj.FormKey));
                            if (baseRec.TopCell != null) return baseRec.TopCell;
                            var copy = r.DeepCopy(ModContextExt.CellCopyMask);
                            baseRec.TopCell = copy;
                            return copy;
                        },
                        duplicateInto: (m, r, e, f) =>
                        {
                            var baseRec = getOrAddAsOverride(m, linkCache.Resolve<IWorldspaceGetter>(obj.FormKey));
                            var dupRec = r.Duplicate(f ?? m.GetNextFormKey(e), ModContextExt.CellCopyMask);
                            baseRec.TopCell = dupRec;
                            return dupRec;
                        }))
                    {
                        yield return item;
                    }
                }
            }
            foreach (var item in obj.SubCells.EnumerateMajorRecordContexts(
                type: typeof(IMajorRecordGetter),
                modKey: modKey,
                parent: curContext,
                linkCache: linkCache,
                throwIfUnknown: false,
                worldspace: obj,
                getOrAddAsOverride: getOrAddAsOverride))
            {
                yield return item;
            }
        }
        
